describe('Search Input Focus on / Key Press', () => {
  beforeEach(() => {
    cy.visit('/search');
  });

  it('should focus search input when / is pressed on keyboard', () => {
    // Verify search input is visible and not focused
    cy.get('[data-testid="search-input"]').should('be.visible');
    cy.get('[data-testid="search-input"]').should('not.have.focus');

    // Press / key
    cy.get('[data-testid="search-input"]').type('/');

    // Verify search input is now focused
    cy.get('[data-testid="search-input"]').should('have.focus');

    // Verify search input contains /
    cy.get('[data-testid="search-input"]').should('contain', '/');
  });

  it('should not focus search input when / is pressed outside of search field', () => {
    // Verify search input is visible and not focused
    cy.get('[data-testid="search-input"]').should('be.visible');
    cy.get('[data-testid="search-input"]').should('not.have.focus');

    // Press / key outside of search field
    cy.get('[data-testid="nav-bar"]').type('/');

    // Verify search input is still not focused
    cy.get('[data-testid="search-input"]').should('not.have.focus');

    // Verify search input still contains /
    cy.get('[data-testid="search-input"]').should('contain', '/');
  });
});
